<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_login();
$page_title='My Found Reports';$s=$pdo->prepare("SELECT i.*,c.name category_name,loc.name location_name,st.name status_name FROM found_items i JOIN categories c ON c.id=i.category_id JOIN locations loc ON loc.id=i.location_id JOIN statuses st ON st.id=i.status_id WHERE i.user_id=? ORDER BY i.created_at DESC");$s->execute([$_SESSION['user']['id']]);$items=$s->fetchAll();
include __DIR__.'/../includes/header.php';?>
<div class="py-4"><div class="d-flex justify-content-between mb-4"><h2 class="section-title">My Found Reports</h2><a href="<?=BASE_URL?>/report_found.php" class="btn btn-primary-glass">New report</a></div><div class="glass-panel table-wrap"><table class="table align-middle"><thead><tr><th>Item</th><th>Category</th><th>Location</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><strong><?=e($i['title'])?></strong></td><td><?=e($i['category_name'])?></td><td><?=e($i['location_name'])?></td><td><span class="badge badge-soft"><?=e($i['status_name'])?></span></td><td><?=date('d M Y',strtotime($i['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php';?>